package com.example

import com.example.ExamQuestionHelper.QSpec

internal object GeographyLiveExamDisastersBank {
  private fun q(t: String, s: String, c: String, d1: String, d2: String, d3: String, e: String) =
    QSpec(t, s, c, listOf(d1, d2, d3), e)

  fun environmentAndDisasterQuestions(): List<QSpec> {
    val t = "පාරිසරික ගැටලු හා ආපදා කළමනාකරණය"
    return listOf(
      q(t, "'උපද්‍රවය' (Hazard) සහ 'ආපදාව' (Disaster) යන සංකල්ප දෙක අතර පවතින මූලික භූගෝලීය වෙනස කුමක්ද?",
        "උපද්‍රවය විභව අනතුරක් වන අතර එය ප්‍රජාවකට බලපා ජීවිතය අඩාල කළ විට ආපදාවක් වේ",
        "උපද්‍රවය හා ආපදාව යනු එකම ස්වාභාවික සිදුවීමක් හැඳින්වීමට යොදන සමාන වචන දෙකක් පමණි",
        "ආපදාව සැමවිටම කුඩා ප්‍රාදේශීය සිදුවීමක් වන අතර උපද්‍රවය ගෝලීය විනාශයක් ඇති කරයි",
        "උපද්‍රවය නාගරික ප්‍රදේශ තුළ පමණක් හටගන්නා අතර ආපදාව ජනශූන්‍ය කාන්තාරවල පමණක් සිදුවේ",
        "ආපදා අවදානම = (උපද්‍රවය × අනාවරණය × අවදානමට ලක්වීමේ ප්‍රවණතාව) / ඔරොත්තු දීමේ හැකියාව ලෙස දැක්වේ."),
      q(t, "ස්වාභාවික උපද්‍රව (Natural Hazards) 'භූගර්භ විද්‍යාත්මක' හා 'ජල-කාලගුණ විද්‍යාත්මක' ලෙස බෙදූ විට භූගර්භ උපද්‍රවයකට නිදසුනක් කුමක්ද?",
        "භූමිකම්පා, ගිනිකඳු විදාරණ සහ සුනාමි",
        "නිවර්තන සුළි කුණාටු, ටොනේඩෝ සහ තද සුළං",
        "දීර්ඝකාලීන නියඟය, තාප තරංග සහ ලැව්ගිනි",
        "ක්ෂණික ගංවතුර, අකුණු සහ හිම කැට වැසි",
        "ගංවතුර, සුළි කුණාටු, නියඟ හා වර්ෂාපතනය ආශ්‍රිත නායයෑම් ජල-කාලගුණ විද්‍යාත්මක උපද්‍රව කාණ්ඩයට අයත් වේ."),
      q(t, "ශ්‍රී ලංකාවේ 'නිරිතදිග මෝසම් හා අන්තර් මෝසම්' කාලවලදී අධික වර්ෂාවත් සමඟ බහුලව ඇතිවන ප්‍රධාන ආපදා දෙක මොනවාද?",
        "ගංවතුර සහ කඳුකර නායයෑම්",
        "සක්‍රීය ගිනිකඳු විදාරණ සහ ලාවා ගැලීම්",
        "ප්‍රබල භූ තැටි භූමිකම්පා සහ අගාධ පැලීම්",
        "ධ්‍රැවීය හිම කුණාටු සහ හිම කඳු කඩා වැටීම්",
        "රත්නපුර, කෑගල්ල, කළුතර, ගාල්ල, මාතර, මහනුවර, නුවරඑළිය, බදුල්ල හා මාතලේ දිස්ත්‍රික්ක නායයෑම් අධි-අවදානම් කලාප ලෙස හඳුනාගෙන ඇත."),
      q(t, "ශ්‍රී ලංකාවේ නායයෑම් පූර්ව අනතුරු ඇඟවීම් නිකුත් කිරීම හා බෑවුම් ස්ථායීතාව පරීක්ෂා කිරීම භාර ප්‍රධාන රාජ්‍ය විද්‍යාත්මක ආයතනය කුමක්ද?",
        "ජාතික ගොඩනැගිලි පර්යේෂණ සංවිධානය (NBRO)",
        "ශ්‍රී ලංකා වාරිමාර්ග දෙපාර්තමේන්තුව",
        "ශ්‍රී ලංකා මිනින්දෝරු දෙපාර්තමේන්තුව",
        "වනජීවී සංරක්ෂණ දෙපාර්තමේන්තුව",
        "පැය 24 ක් තුළ මි.මී. 75, 100 හෝ 150 ඉක්මවන වර්ෂාපතනයක් ලැබුණු විට NBRO ආයතනය කහ, තැඹිලි හා රතු නිවේදන නිකුත් කරයි."),
      q(t, "කඳුකර ප්‍රදේශවල 'නායයෑමක පූර්ව ලක්ෂණ' (Early Warning Signs) ලෙස ජනතාව වහාම අවධානය යොමු කළ යුතු සංඥා මොනවාද?",
        "පොළොවේ හෝ බිත්තිවල පැලීම් ඇතිවීම, ගස් ඇලවීම සහ උල්පත් එක්වරම බොර වීමයි",
        "අහස සම්පූර්ණයෙන්ම වලාකුළු වලින් තොරව නිල් පැහැති වී වියළි සුළං හැමීමයි",
        "කඳු බෑවුම්වල සාමාන්‍යයෙන් පවතින හරිත ශාකවල මල් පිපීම හා පරාගණය වැඩි වීමයි",
        "මුහුදු වෙරළ තීරයේ සාමාන්‍ය වඩදිය මට්ටම දිවා කාලයේදී සුළු වශයෙන් වෙනස් වීමයි",
        "මෙවැනි ලක්ෂණ දුටු වහාම රාත්‍රී නින්දට පෙර ආරක්ෂිත ස්ථාන වෙත ඉවත් වීම ජීවිත බේරා ගැනීමට තීරණාත්මකය."),
      q(t, "ශ්‍රී ලංකාවේ ඕනෑම හදිසි ආපදාවක් පිළිබඳව දැනුම් දීමට 'ආපදා කළමනාකරණ මධ්‍යස්ථානය' (DMC) හඳුන්වා දී ඇති පැය 24 හදිසි ඇමතුම් අංකය කුමක්ද?",
        "117", "119", "1990", "1919",
        "117 මධ්‍යස්ථානය කාලගුණ විද්‍යා දෙපාර්තමේන්තුව, NBRO, වාරිමාර්ග දෙපාර්තමේන්තුව හා ත්‍රිවිධ හමුදාව සමඟ සම්බන්ධීකරණයෙන් කටයුතු කරයි."),
      q(t, "'ආපදා කළමනාකරණ චක්‍රයේ' (Disaster Management Cycle) ප්‍රධාන අදියර හතර නිවැරදි අනුපිළිවෙළින් දැක්වෙන්නේ කුමක්ද?",
        "අවම කිරීම → පෙර සූදානම → ප්‍රතිචාර දැක්වීම → යථා තත්ත්වයට පත් කිරීම",
        "ප්‍රතිචාර දැක්වීම → හානි මැනීම → පලා යාම → ඉඩම් අත්හැර දැමීම",
        "යථා තත්ත්වය → අනතුරු හැඟවීම → අවදානම වැඩි කිරීම → ආපදාව සිදුවීම",
        "පූර්ව විනාශය → පරිසර දූෂණය → සහන බෙදීම → ස්වාභාවික ව්‍යසනය",
        "ආපදාවක් සිදුවීමට පෙර ක්‍රියාත්මක වන Mitigation සහ Preparedness මගින් ජීවිත හා දේපළ හානි විශාල ලෙස අඩු කළ හැකිය."),
      q(t, "'සෙන්ඩායි ආපදා අවදානම් අවම කිරීමේ රාමුව' (Sendai Framework 2015–2030) මගින් ලෝකයට ලබා දෙන ප්‍රධාන පණිවිඩය කුමක්ද?",
        "ආපදා පසු සහන සැලසීමට වඩා කලින්ම ආපදා අවදානම අවම කිරීමට ආයෝජනය කිරීමයි",
        "සියලුම පූර්ව අනතුරු ඇඟවීමේ පද්ධති නවතා ආපදා සිදු වූ පසු පමණක් ක්‍රියාත්මක වීමයි",
        "වෙරළබඩ තෙත් බිම් හා ගංගා ඉවුරු මත විශාල වාණිජ නගර පමණක් ඉදිකිරීමයි",
        "ජාත්‍යන්තර ආපදා සහන අරමුදල් අවලංගු කර එක් එක් ග්‍රාමය හුදෙකලා කිරීමයි",
        "'වඩා හොඳින් යළි ගොඩනැගීම' (Build Back Better) යන්න මෙහි ප්‍රධාන ප්‍රමුඛතාවකි."),
      q(t, "'සුනාමි' (Tsunami) රළක් සාමාන්‍යයෙන් ජනනය වන්නේ කුමන සාගර පතුලේ සිදුවන ක්‍රියාවලියක් නිසාද?",
        "මුහුදු පතුලේ ප්‍රබල භූමිකම්පා, දිය යට ගිනිකඳු පිපිරීම් හෝ නායයෑම් නිසාය",
        "වෙරළ තීරය දිගේ හමන සාමාන්‍ය නිරිතදිග මෝසම් සුළං ප්‍රවාහය නිසාය",
        "චන්ද්‍රයාගේ ගුරුත්වාකර්ෂණය මගින් ඇති වන දෛනික වඩදිය බාදිය චක්‍රය නිසාය",
        "ගැඹුරු සාගරයේ ගමන් කරන වාණිජ බහාලුම් නැව් හා ධීවර බෝට්ටු නිසාය",
        "2004 දෙසැම්බර් 26 ඉන්දියානු සාගර සුනාමිය සුමාත්‍රා වෙරළට ඔබ්බෙන් ඇති වූ රිච්ටර් මාපක 9.1–9.3 ක භූමිකම්පාවකින් ජනිත විය."),
      q(t, "ගැඹුරු සාගරයේ සිට නොගැඹුරු වෙරළට ළඟා වන විට සුනාමි තරංගයේ හැසිරීම වෙනස් වන්නේ කෙසේද?",
        "ගැඹුරු සාගරයේ අධිවේගයෙන් හා අඩු උසකින් ගමන් කර වෙරළේදී වේගය අඩු වී උස ඉහළ නැගීමයි",
        "ගැඹුරු සාගරයේදී මීටර් 30 ක් උසට ගමන් කර වෙරළ තීරයට ළඟා වන විට අතුරුදහන් වීමයි",
        "වෙරළ තීරයට ළඟා වන විට තරංගයේ උස බින්දුවට බැස වේගය දෙගුණයකින් ඉහළ යාමයි",
        "නොගැඹුරු මුහුදේදී තරංගය සම්පූර්ණයෙන්ම හිම තට්ටුවක් බවට මිදී ගොඩබිම මත නැවතීමයි",
        "සුනාමියට පෙර මුහුදු ජලය අසාමාන්‍ය ලෙස පසුපසට ඇදී යාම (Drawback) ක්ෂණිකව උස් බිමකට පලා යා යුතු පූර්ව ස්වාභාවික සංඥාවකි."),
      q(t, "2004 සුනාමි ව්‍යසනයෙන් පසු ඉන්දියානු සාගර කලාපයේ රටවල් ආරක්ෂා කිරීමට පිහිටුවන ලද ජාත්‍යන්තර පද්ධතිය කුමක්ද?",
        "ඉන්දියානු සාගර සුනාමි පූර්ව අනතුරු ඇඟවීමේ පද්ධතිය (IOTWMS)",
        "උතුරු අප්‍රිකානු සහරා කාන්තාර කාලගුණ නිරීක්ෂණ පද්ධතිය",
        "උතුරු ඇමෙරිකානු හිම කුණාටු පුරෝකථන මධ්‍යස්ථානය",
        "මධ්‍යම යුරෝපා ඇල්ප්ස් කඳුකර ගිනිකඳු ජාල පද්ධතිය",
        "ශ්‍රී ලංකාවේ වෙරළ තීරය දිගේ 'සුනාමි පූර්ව අනතුරු ඇඟවීමේ කුළුණු' (Early Warning Towers) ස්ථාපිත කර ඇත."),
      q(t, "නාගරික ප්‍රදේශවල (උදා: කොළඹ, ගම්පහ) කෙටි තද වැස්සකින් පසුව පවා 'ක්ෂණික නාගරික ගංවතුර' (Urban Flash Floods) ඇතිවීමට ප්‍රධාන මානව හේතුව කුමක්ද?",
        "තෙත් බිම් ගොඩකිරීම, කොන්ක්‍රීට් ආවරණ වැඩි වීම හා කාණු පද්ධති කසළවලින් අවහිර වීමයි",
        "නගර තුළ වනාන්තර හා තෙත් බිම් ප්‍රමාණය ස්වාභාවිකවම දෙගුණයකින් ඉහළ යාමයි",
        "නාගරික ප්‍රදේශවල වාර්ෂික වර්ෂාපතනය සම්පූර්ණයෙන්ම බින්දුව දක්වා පහළ වැටීමයි",
        "වැසි ජලය පොළොවට අධික ලෙස කාන්දු වී භූගත ජල මට්ටම සිඳී යාමයි",
        "නාගරික ගංවතුර පාලනය සඳහා 'ස්පොන්ජ් නගර' (Sponge Cities - උදා: බැද්දගාන තෙත් බිම් උද්‍යානය වැනි රැඳවුම් උද්‍යාන) සංකල්පය භාවිත කෙරේ."),
      q(t, "'හරිතාගාර ආචරණය' (Greenhouse Effect) සහ 'වැඩි දියුණු කළ හරිතාගාර ආචරණය' (Global Warming) අතර වෙනස කුමක්ද?",
        "ස්වාභාවික හරිතාගාර ආචරණය ජීවයට හිතකර ~15°C උෂ්ණත්වයක් පවත්වා ගන්නා අතර අතිරික්ත CO2 නිසා වැඩි දියුණු කළ ආචරණයෙන් ගෝලීය උණුසුම ඇති වේ",
        "ස්වාභාවික හරිතාගාර ආචරණය මගින් පෘථිවිය සෙල්සියස් අංශක -18°C දක්වා සිසිල් කරන අතර වැඩි දියුණු කළ ආචරණයෙන් අයිස් යුගයක් බිහි වේ",
        "හරිතාගාර ආචරණයන් දෙකම සම්පූර්ණයෙන්ම කර්මාන්තශාලා දුමාරය නිසා පමණක් හටගන්නා බැවින් ස්වාභාවික වායුගෝලයට කිසිදු සම්බන්ධයක් නොමැත",
        "කාබන් ඩයොක්සයිඩ් හා මීතේන් වායු තාපය උරා නොගන්නා බැවින් ගෝලීය උණුසුම සඳහා බලපාන්නේ ඔක්සිජන් හා නයිට්‍රජන් වායු පමණි",
        "ස්වාභාවික හරිතාගාර ආචරණය නොතිබුණේ නම් පෘථිවියේ සාමාන්‍ය උෂ්ණත්වය -18°C පමණ වී ජලය මිදී පවතිනු ඇත."),
      q(t, "ප්‍රධාන හරිතාගාර වායු අතර 'මීතේන්' (CH4) වායුව කාබන් ඩයොක්සයිඩ් (CO2) ට වඩා ප්‍රබල වන්නේ ඇයි සහ එහි ප්‍රභව මොනවාද?",
        "CO2 ට වඩා වැඩි තාප රඳවා ගැනීමේ බලයක් ඇති අතර සත්ත්ව පාලනය, වී වගාව හා කසළ කඳු වලින් පිටවේ",
        "සාගරයේ කොරල් පර හා හරිත ශාක මගින් ප්‍රභාසංශ්ලේෂණයේදී පමණක් මීතේන් වායුව වායුගෝලයට නිපදවේ",
        "මීතේන් වායුව සූර්ය තාපය රඳවා නොගෙන පෘථිවියේ වායුගෝලය ක්ෂණිකව සිසිල් කිරීමට උපකාරී වේ",
        "මීතේන් වායුව ඉහළ අපරිවර්තී ගෝලයේදී හානිකර පාරජම්බුල කිරණ වළක්වන ඕසෝන් ස්තරය නිර්මාණය කරයි",
        "කෙසේ වෙතත් මීතේන් වායුගෝලයේ රැඳී සිටින කාලය (~අවුරුදු 12) CO2 ට වඩා කෙටි බැවින් එය පාලනය කිරීමෙන් ඉක්මන් ප්‍රතිඵල ලැබේ."),
      q(t, "'අම්ල වැසි' (Acid Rain - pH අගය 5.6 ට අඩු) ඇති වීමට ප්‍රධාන වශයෙන් හේතු වන කාර්මික හා රථවාහන වායු දූෂක දෙක මොනවාද?",
        "සල්ෆර් ඩයොක්සයිඩ් (SO2) සහ නයිට්‍රජන් ඔක්සයිඩ් (NOx)",
        "වායුගෝලීය ඔක්සිජන් (O2) සහ නයිට්‍රජන් (N2)",
        "නිෂ්ක්‍රීය වායු වන හීලියම් (He) සහ ආගන් (Ar)",
        "මිරිදිය ජලාශවලින් නැගෙන පිරිසිදු ජල වාෂ්ප (H2O)",
        "අම්ල වැසි නිසා විල්වල මසුන් මිය යාම, වනාන්තර කොළ හැලීම, පස නිසරු වීම සහ හුණුගල්/මාබල් ස්මාරක (උදා: ටජ් මහල) ඛාදනය වීම සිදුවේ."),
      q(t, "පාරජම්බුල කිරණ (UV-B) පෙරා හරින අපරිවර්තී ගෝලයේ (Stratosphere) පිහිටි 'ඕසෝන් ස්තරය' සිදුරු වීමට හේතු වූ ප්‍රධාන රසායනික ද්‍රව්‍ය කුමක්ද?",
        "ශීතකරණ හා වායු සමීකරණවල භාවිත කළ ක්ලෝරෝෆ්ලෝරෝකාබන් (CFC) වායුය",
        "රථවාහන දුමෙන් පිටවන කාබන් මොනොක්සයිඩ් (CO) වායුව පමණය",
        "පෘථිවි වායුගෝලයේ ස්වාභාවිකව පවතින පිරිසිදු නයිට්‍රජන් (N2) වායුවය",
        "සාගර ජලය වාෂ්ප වීමෙන් ඉහළ නැගෙන මිරිදිය ජල වාෂ්ප වලාකුළුය",
        "1987 'මොන්ට්‍රියල් සන්ධානය' (Montreal Protocol) මගින් CFC තහනම් කිරීම නිසා ඕසෝන් ස්තරය දැන් ක්‍රමයෙන් සුව වෙමින් පවතී."),
      q(t, "1987 'මොන්ට්‍රියල් සන්ධානය' (Montreal Protocol) හා 2015 'පැරිස් ගිවිසුම' (Paris Agreement) අතර ප්‍රධාන අරමුණු වෙනස කුමක්ද?",
        "මොන්ට්‍රියල් සන්ධානය CFC තහනම් කිරීම සඳහා වන අතර පැරිස් ගිවිසුම ගෝලීය උණුසුම 1.5°C–2°C ට අඩුවෙන් තැබීමටය",
        "මොන්ට්‍රියල් සන්ධානය ප්ලාස්ටික් නිෂ්පාදනය වැඩි කිරීමට වන අතර පැරිස් ගිවිසුම ගල් අඟුරු පතල් විවෘත කිරීමටය",
        "පැරිස් ගිවිසුම ඕසෝන් ස්තරය විශාල කිරීමට වන අතර මොන්ට්‍රියල් සන්ධානය කාබන් විමෝචනය දෙගුණ කිරීමටය",
        "මෙම ජාත්‍යන්තර ගිවිසුම් දෙකම සාගර මත්ස්‍ය සම්පත් බෙදාගැනීම හා න්‍යෂ්ටික අවි නිෂ්පාදනය පිළිබඳ ගිවිසුම් වේ",
        "මොන්ට්‍රියල් සන්ධානය ඉතිහාසයේ වඩාත්ම සාර්ථක ජාත්‍යන්තර පාරිසරික ගිවිසුම ලෙස සැලකේ."),
      q(t, "නාගරික වායු දූෂණයේදී 'ප්‍රකාශ රසායනික දුමාරය' (Photochemical Smog) නිර්මාණය වන්නේ කෙසේද?",
        "නයිට්‍රජන් ඔක්සයිඩ් හා VOCs හිරු එළිය සමඟ ප්‍රතික්‍රියා කර බිම් මට්ටමේ ඕසෝන් හා දුමාරය සෑදීමෙනි",
        "ධ්‍රැවීය කලාපවල හිම පතනය හා අධික ශීතල සුළං ප්‍රවාහයන් නගරය තුළට හමා ඒමෙනි",
        "නාගරික මාර්ග දෙපස විශාල වශයෙන් හරිත ශාක සිටුවා ඔක්සිජන් ප්‍රමාණය වැඩි කිරීමෙනි",
        "වැසි වලාකුළු වලින් පතිත වන පිරිසිදු වර්ෂාපතනය හේතුවෙන් නගරයේ වාතය සිසිල් වීමෙනි",
        "උස් අපරිවර්තී ගෝලයේ ඕසෝන් 'හොඳ ඕසෝන්' වන අතර පොළොව මට්ටමේ ඕසෝන් පෙනහළුවලට හානි කරන 'නරක ඕසෝන්' වේ."),
      q(t, "වායු ගුණාත්මක දර්ශකයේදී (AQI) මනිනු ලබන 'PM2.5' අංශු (විෂ්කම්භය මයික්‍රොමීටර 2.5 ට අඩු) සෞඛ්‍යයට අතිශය භයානක වන්නේ ඇයි?",
        "ඒවා ඉතා කුඩා බැවින් පෙනහළු ගැඹුරට හා රුධිර පද්ධතියට ඇතුළු වී හෘද හා ශ්වසන රෝග ඇති කරන බැවිනි",
        "එක් PM2.5 අංශුවක් කිලෝග්‍රෑමයකට වඩා බරින් යුක්ත වන බැවින් ගොඩනැගිලි වහලවල් කඩා වැටෙන බැවිනි",
        "ඒවා මිනිස් නාසයේ පෙරහන් මගින් සම්පූර්ණයෙන්ම පෙරී ශරීරයට කිසිසේත්ම ඇතුළු නොවන බැවිනි",
        "එම අංශු වායුගෝලයේදී ප්‍රභාසංශ්ලේෂණය සිදු කරමින් මිනිස් සිරුරට අවශ්‍ය පිරිසිදු ඔක්සිජන් නිපදවන බැවිනි",
        "ඩීසල් වාහන දුම, ගල් අඟුරු බලාගාර, අපද්‍රව්‍ය පිළිස්සීම හා ඉදිකිරීම් දූවිලි PM2.5 ප්‍රධාන ප්‍රභව වේ."),
      q(t, "කෘෂිකාර්මික පොහොර හා අපජලය වැව්වලට ගලා යාමෙන් සිදුවන 'සුපෝෂණය' (Eutrophication) නිසා මසුන් මිය යන්නේ කෙසේද?",
        "ඇල්ගී අධිකව වැඩී දිරාපත් වීමේදී ජලයේ දියවූ ඔක්සිජන් වැය වී මළ කලාප සෑදීමෙනි",
        "ජලාශයේ දියවූ ඔක්සිජන් ප්‍රමාණය සාමාන්‍ය මට්ටමට වඩා දස ගුණයකින් ඉහළ යාමෙනි",
        "නයිට්‍රේට් පොහොර නිසා වැව් ජලය ක්ෂණිකව ඝන අයිස් තට්ටුවක් බවට පත් වීමෙනි",
        "මසුන්ට අවශ්‍ය ස්වාභාවික ආහාර අධික ලෙස වැඩි වී මසුන්ගේ ප්‍රමාණය විශාල වීමෙනි",
        "බේරේ වැව, මහනුවර වැව හා කැලණි/බොල්ගොඩ පද්ධති ආශ්‍රිතව මෙවැනි ජල දූෂණ අවදානම් නිරීක්ෂණය වී ඇත."),
      q(t, "'ජෛව සමුච්චනය හා ජෛව විශාලනය' (Bioaccumulation & Biomagnification) මගින් පරිසර දූෂක ආහාර දාමයට බලපාන්නේ කෙසේද?",
        "රසදිය හා DDT වැනි නොදිරන විෂ ආහාර දාමයේ ඉහළ පෝෂණ මට්ටම් වෙත යත්ම සාන්ද්‍රණය වැඩි වීමෙනි",
        "ආහාර දාමයේ ඉහළ පෝෂණ මට්ටම් වෙත ගමන් කරන විට විෂ ද්‍රව්‍ය සම්පූර්ණයෙන්ම වාෂ්ප වී නැති වීමෙනි",
        "විෂ රසායනික ද්‍රව්‍ය ජලජ ශාකවල මුල්වල පමණක් රැඳී කිසිදු සතෙකුගේ ශරීරයට ඇතුළු නොවීමෙනි",
        "මුහුදු ජලයේ ඇති ලුණු සමඟ ප්‍රතික්‍රියා කර විෂ ද්‍රව්‍ය සියල්ල පෝෂ්‍යදායී විටමින් බවට පත් වීමෙනි",
        "ජපානයේ මිනමාටා රෝගය (රසදිය විෂවීම) ජෛව විශාලනයේ ඛේදනීය ඓතිහාසික නිදසුනකි."),
      q(t, "'ඉලෙක්ට්‍රොනික අපද්‍රව්‍ය' (E-waste - පැරණි දුරකථන, පරිගණක, බැටරි) සාමාන්‍ය කසළ සමඟ පිළිස්සීම හෝ වැළලීම අතිශය භයානක වන්නේ ඇයි?",
        "ඊයම්, රසදිය, කැඩ්මියම් හා ආසනික් අඩංගු බැවින් භූගත ජලය හා වාතය විෂ වන බැවිනි",
        "ඒවා කාබනික පොහොර සෑදීමට ඉතා සුදුසු බැවින් පසෙහි පණුවන් අධික ලෙස බෝ වන බැවිනි",
        "ප්ලාස්ටික් හා පරිපථ පුවරු පැය කිහිපයක් ඇතුළත සම්පූර්ණයෙන්ම ජීව විද්‍යාත්මකව දිරාපත් වන බැවිනි",
        "ඒවා වැළලීමෙන් පසට නයිට්‍රජන් එක් වී කෘෂිකාර්මික ශාක වර්ධනය අධික ලෙස වේගවත් වන බැවිනි",
        "E-waste නිසි ප්‍රතිචක්‍රීකරණ ආයතන වෙත භාර දීමෙන් රන්, රිදී, තඹ හා දුර්ලභ ලෝහද නැවත ලබාගත හැකිය."),
      q(t, "'ක්ෂුද්‍ර ප්ලාස්ටික්' (Microplastics - මි.මී. 5 ට කුඩා ප්ලාස්ටික් කැබලි) සාගර පරිසරයට හා ආහාර ජාලයට ඇතුළු වන්නේ කෙසේද?",
        "ප්ලාස්ටික් අපද්‍රව්‍ය හිරු එළියෙන් හා රළ පහරින් කැඩීමෙන්, රෙදි සේදීමේ කෙඳිවලින් හා ටයර් ගෙවීමෙනි",
        "ගැඹුරු සාගර පතුලේ ඇති ග්‍රැනයිට් හා බැසෝල්ට් ගල් පර්වත මුහුදු ජලයේ දිය වී යාමෙනි",
        "අහසේ වැසි වලාකුළු ඝනීභවනය වීමේදී ස්වාභාවික වර්ෂාපතනය සමඟ කෘත්‍රිම ප්ලාස්ටික් ඉබේ සෑදීමෙනි",
        "සාගරයේ ජීවත් වන කොරල් හා මසුන් විසින් තම ආරක්ෂාව සඳහා කෘත්‍රිම ප්ලාස්ටික් නිපදවීමෙනි",
        "2021 දී ශ්‍රී ලංකාවේ බටහිර වෙරළට ඔබ්බෙන් සිදු වූ MV X-Press Pearl නෞකා අනතුරින් විශාල ප්ලාස්ටික් කැටිති (Nurdles) වෙරළට ගොඩ ගැසී දැඩි සාගර හානියක් සිදුවිය."),
      q(t, "'වන විනාශය' (Deforestation) ගෝලීය දේශගුණික විපර්යාසයට දෙයාකාරයකින්ම දායක වන්නේ කෙසේද?",
        "ගස් පිළිස්සීමෙන් ගබඩා වූ කාබන් මුදා හැරෙන අතරම CO2 උරා ගන්නා කාබන් අවශෝෂකයද අහිමි වේ",
        "වනාන්තර කපා දැමීමෙන් පෘථිවියේ සාමාන්‍ය උෂ්ණත්වය පහළ බැස සිසිල් දේශගුණයක් ඇති වේ",
        "වන විනාශය හේතුවෙන් වායුගෝලයේ ඇති කාබන් ඩයොක්සයිඩ් හා මීතේන් ප්‍රමාණය සීඝ්‍රයෙන් අඩු වේ",
        "ශාක ඉවත් කිරීමෙන් වාෂ්පෝත්ස්වේදනය වැඩි වී කාන්තාර ප්‍රදේශවල වර්ෂාපතනය දෙගුණ වේ",
        "ඇමසන් වනයේ වන විනාශය හා ඉන්දුනීසියාවේ පීට් වනාන්තර පිළිස්සීම ගෝලීය කාබන් විමෝචනයට ප්‍රධාන හේතුවකි."),
      q(t, "'කාන්තාරීකරණය' (Desertification) යන පාරිසරික ගැටලුව නිවැරදිවම නිර්වචනය කරන්නේ කුමක් ලෙසද?",
        "නියඟය හා අධික තෘණ කැවීම වැනි මානව ක්‍රියා නිසා ශුෂ්ක හා අර්ධ-ශුෂ්ක ඉඩම් නිසරු වීමයි",
        "අප්‍රිකාවේ සහරා කාන්තාරය භූ තැටි චලනය නිසා සම්පූර්ණයෙන්ම අත්ලාන්තික් සාගරයට ගිලී යාමයි",
        "නාගරික ප්‍රදේශයක ළමා උද්‍යානයක් තුළ වැලි පිට්ටනියක් ඉදිකිරීමේ ඉංජිනේරු ක්‍රියාවලියයි",
        "සමක කලාපයේ පිහිටි සදාහරිත වැසි වනාන්තර වර්ෂාපතනය වැඩි වීම නිසා ව්‍යාප්ත වීමයි",
        "අප්‍රිකාවේ 'මහා හරිත පවුර' (Great Green Wall) ව්‍යාපෘතිය සහෙල් කලාපයේ කාන්තාරීකරණය නැවැත්වීමේ දැවැන්ත උත්සාහයකි."),
      q(t, "භූමිකම්පාවක ප්‍රබලතාව මනින 'මොමන්ට් මැග්නිටියුඩ් පරිමාණය' (Mw) සහ 'මර්කලි තීව්‍රතා පරිමාණය' (Mercalli) අතර වෙනස කුමක්ද?",
        "Mw පරිමාණය මුදා හැරුණු භෞතික ශක්තිය මනින අතර මර්කලි පරිමාණය සිදුවූ හානිය හා දැනුණු ප්‍රමාණය මනී",
        "මෙම පරිමාණ දෙකම සුළි කුණාටුවක මධ්‍යම සුළං වේගය හා වායු පීඩනය මැනීම සඳහා භාවිත කෙරේ",
        "මර්කලි පරිමාණය සක්‍රීය ගිනිකඳු කේතුවක උස මනින අතර Mw පරිමාණය ලාවා උෂ්ණත්වය මනී",
        "මැග්නිටියුඩ් පරිමාණය වාර්ෂික වර්ෂාපතනය මනින අතර මර්කලි පරිමාණය සාගර ලවණතාව මනී",
        "රිච්ටර්/මොමන්ට් පරිමාණයේ එක් පූර්ණ සංඛ්‍යාවකින් (උදා: 6 සිට 7 දක්වා) ශක්තිය ~32 ගුණයකින් වැඩි වේ."),
      q(t, "භූමිකම්පාවක 'නාභිය' (Focus / Hypocenter) සහ 'අපිකේන්ද්‍රය' (Epicenter) යන ස්ථාන දෙක හඳුනා ගන්නේ කෙසේද?",
        "නාභිය පොළොව අභ්‍යන්තරයේ භූමිකම්පාව ඇරඹෙන ස්ථානය වන අතර අපිකේන්ද්‍රය ඊට ඉහළින් පෘෂ්ඨයේ පිහිටයි",
        "අපිකේන්ද්‍රය සැමවිටම මුහුදු පතුලට කිලෝමීටර 500 ක් යටින් පිහිටන අතර නාභිය වෙරළේ පිහිටයි",
        "නාභිය පෘථිවි වායුගෝලයේ ඉහළ ස්තරවල පිහිටන අතර අපිකේන්ද්‍රය චන්ද්‍රයා මත පිහිටයි",
        "නාභිය හා අපිකේන්ද්‍රය අතර කිසිදු සිරස් සම්බන්ධයක් නැති අතර ඒවා කිලෝමීටර දහස් ගණනක් ඈතින් පිහිටයි",
        "සාමාන්‍යයෙන් අපිකේන්ද්‍රය අසලදී භූමිකම්පා හානිය වැඩි වන අතර නොගැඹුරු නාභි (Shallow Focus) භූමිකම්පා වඩාත් විනාශකාරී වේ."),
      q(t, "ජපානයේ හා චිලී රාජ්‍යයේ ඉතා ප්‍රබල භූමිකම්පා ඇති වුවද ජීවිත හානි අඩු මට්ටමක තබා ගැනීමට සමත් වී ඇත්තේ කුමන පියවර නිසාද?",
        "භූ-කම්පන ප්‍රතිරෝධී ගොඩනැගිලි නීති, Base Isolation කම්පන අවශෝෂක හා පෙරහුරු මගිනි",
        "රටේ සියලුම නගර හා ගම්මාන සම්පූර්ණයෙන්ම හිස් කර ජනතාව නැව්වල පදිංචි කරවීම මගිනි",
        "බහුමහල් ගොඩනැගිලි සෑදීමේදී වානේ ඉවත් කර ගඩොල් හා මැටිවලින් පමණක් ගොඩනැගීම මගිනි",
        "භූ තැටි චලනය සම්පූර්ණයෙන්ම නවතා දමන විශාල චුම්භක යන්ත්‍ර පොළොව යට සවි කිරීම මගිනි",
        "'මිනිසුන් මරන්නේ භූමිකම්පා නොවේ, දුර්වල ගොඩනැගිලිය' යන්න ආපදා කළමනාකරණයේ ප්‍රසිද්ධ කියමනකි."),
      q(t, "'නාගරික තාප දූපත' (Urban Heat Island) යන පාරිසරික ගැටලුව ඇතිවීමට ප්‍රධාන හේතුව කුමක්ද?",
        "තාර මාර්ග, කොන්ක්‍රීට් ගොඩනැගිලි, වාහන තාපය හා ගස් අඩුවීම නිසා නගර උණුසුම් වීමයි",
        "නාගරික ප්‍රදේශවල ග්‍රාමීය ප්‍රදේශවලට වඩා ඝන හරිත වනාන්තර හා තුරුලතා වැඩි වීමයි",
        "නගර මධ්‍යයේ විශාල මිරිදිය වැව් හා සිසිල් ජල උද්‍යාන අධික ලෙස පිහිටා තිබීමයි",
        "සෑම වසරකම ශීත ඍතුවේදී නාගරික මාර්ග මත අධික ලෙස හිම පතනය සිදුවීමයි",
        "නාගරික වන වගා (Urban Forestry), සෙවණ මාර්ග, සුදු පැහැති සිසිල් වහලවල් (Cool Roofs) හා හරිත බිත්ති මගින් මෙම උණුසුම අඩු කළ හැකිය."),
      q(t, "ශ්‍රී ලංකාවේ 'අලි-මිනිස් ගැටුම' (Human-Elephant Conflict) ඇතිවීමට ප්‍රධානම භූගෝලීය හේතුව කුමක්ද?",
        "වන අලින්ගේ සාම්ප්‍රදායික වන මංකඩ හා වාසභූමි අවහිර කරමින් වගා බිම් හා ජනාවාස ව්‍යාප්ත වීමයි",
        "වියළි කාලයේදී වන අලින් සාමාන්‍යයෙන් ජලය පානය කිරීම හා ස්නානය කිරීම නවතා දැමීමයි",
        "ඉන්දියන් සාගරයේ මුහුදු මට්ටම ඉහළ යාම නිසා මුළු මධ්‍යම කඳුකරයම ජලයෙන් යට වීමයි",
        "රටේ ස්වාභාවික වනාන්තර ආවරණය පසුගිය දශකය තුළ දෙගුණයකින් ඉහළ යාමයි",
        "වන අලි රක්ෂිත අතර ස්වාභාවික වන මංකඩ නැවත විවෘත කිරීම, විද්‍යුත් වැටවල් නිසි නඩත්තුව හා අලි ගමන් කළ හැකි උමං/පාලම් ඉදිකිරීම තිරසාර විසඳුම් වේ."),
      q(t, "'ආක්‍රමණශීලී ආගන්තුක ජීවීන්' (උදා: ජපන් ජබර, සැල්වීනියා, ගඳපාන, ටැංකි සුද්දා) පරිසර පද්ධතිවලට තර්ජනයක් වන්නේ ඇයි?",
        "ස්වාභාවික සතුරන් නැති පරිසරයක වේගයෙන් බෝ වී දේශීය හා ආවේණික විශේෂ යටපත් කරන බැවිනි",
        "ඔවුන් දේශීය ශාක හා මත්ස්‍ය විශේෂ විලෝපිකයන්ගෙන් ආරක්ෂා කරමින් රැක ගන්නා බැවිනි",
        "වැව් හා වනාන්තරවල ස්වාභාවික ජෛව විවිධත්වය දස ගුණයකින් වර්ධනය කිරීමට උදව් වන බැවිනි",
        "නව පරිසරයට හඳුන්වා දීමෙන් පැය කිහිපයක් ඇතුළත සියල්ලම ස්වාභාවිකවම මිය යන බැවිනි",
        "නොදැනුවත්ව හෝ විසිතුරු සතුන්/ශාක ලෙස ගෙන්වා පරිසරයට මුදා හැරීම මෙම ගැටලුවට ප්‍රධාන හේතුවයි."),
      q(t, "'නියඟය' (Drought) අනෙකුත් ක්ෂණික ආපදාවලින් වෙනස්ව 'සෙමින් ඇරඹෙන ආපදාවක්' (Slow-onset Disaster) ලෙස හඳුන්වන්නේ ඇයි?",
        "සති හා මාස ගණනක් පුරා වැසි අඩු වී කෘෂිකර්මයට හා ජල සැපයුමට දීර්ඝකාලීන හානි කරන බැවිනි",
        "භූමිකම්පාවක් මෙන් තත්පර කිහිපයකින් ආරම්භ වී මිනිත්තුවකින් සම්පූර්ණයෙන්ම අවසන් වන බැවිනි",
        "ගැඹුරු සාගර පතුලේදී පමණක් හටගන්නා බැවින් ගොඩබිම් ප්‍රජාවට කිසිදු බලපෑමක් නැති බැවිනි",
        "නියඟය නිසා පසෙහි තෙතමනය හා ගංගා ජල මට්ටම් වේගයෙන් ඉහළ ගොස් ගංවතුර ඇති වන බැවිනි",
        "කාලගුණ විද්‍යාත්මක, කෘෂිකාර්මික, ජල විද්‍යාත්මක හා සමාජ-ආර්ථික නියඟ ලෙස එහි අදියර හතරක් හඳුනාගනී."),
      q(t, "'කාලගුණික නියඟ අවම කිරීමේදී' ශ්‍රී ලංකාවේ පුරාණ 'එල්ලංගා වැව් පද්ධතිය' (Cascading Tank System) අදටත් විශිෂ්ට වන්නේ ඇයි?",
        "නිම්නයේ ඉහළ සිට පහළට සම්බන්ධ වැව් මගින් වැසි ජලය රඳවා භූගත ජලය පෝෂණය කරන බැවිනි",
        "මෝසම් වැසි ජලය කිසිදු පාලනයකින් තොරව එකවරම කෙලින්ම මහා සාගරයට හරවා යවන බැවිනි",
        "වැව් ජලය ඉක්මනින් වාෂ්ප කර වියළි කලාපයේ වායුගෝලීය උෂ්ණත්වය ඉහළ දමන බැවිනි",
        "තියුණු කඳු මුදුන්වල ගල් පර්වත මත ඉදිකර ඇති බැවින් කුඹුරුවලට ජලය නොයන බැවිනි",
        "FAO ආයතනය විසින් ශ්‍රී ලංකාවේ එල්ලංගා වැව් ගොවි පද්ධතිය 'ගෝලීය වශයෙන් වැදගත් කෘෂිකාර්මික උරුමයක්' (GIAHS) ලෙස නම් කර ඇත."),
      q(t, "'ලැව් ගිනි' (Wildfires) හටගැනීමට හා වේගයෙන් පැතිරීමට දායක වන ප්‍රධාන ස්වාභාවික හා මානව සාධක මොනවාද?",
        "දීර්ඝ නියඟ, අධික උණුසුම හා වියළි සුළං සමඟ කැලෑ එළි කිරීමට මිනිසුන් ගිනි තැබීම",
        "නොනවතින ධාරානිපාත මෝසම් වැසි හා ගංගා පිටාර ගැලීම නිසා පස තෙත් වීම",
        "ඉහළ කඳුකර ප්‍රදේශවල ශීතල හිම කුණාටු හා අධික පිනි පතිත වීම නිසා තුරුලතා වැසීම",
        "වායුගෝලයේ සාපේක්ෂ ආර්ද්‍රතාව සියයට අනූව ඉක්මවා ඉහළ යාම හා වලාකුළු ඝන වීම",
        "ශ්‍රී ලංකාවේ නකල්ස්, බදුල්ල, මොණරාගල හා පයිනස් වගා බිම්වල වියළි කාලයේදී මානව ගිනි තැබීම් නිසා ලැව් ගිනි බහුලව වාර්තා වේ."),
      q(t, "'කසළ කළමනාකරණයේ ධූරාවලිය' (Waste Management Hierarchy) අනුව වඩාත්ම ප්‍රමුඛත්වය දිය යුතු පළමු පියවර හා අවසාන පියවර පිළිවෙළින් කුමක්ද?",
        "පළමු ප්‍රමුඛතාව ලෙස අපද්‍රව්‍ය ජනනය අවම කිරීමත් අවසාන පියවර ලෙස ක්‍රමවත් බැහැර කිරීමත් යොදා ගැනීම",
        "පළමු ප්‍රමුඛතාව ලෙස විවෘත භූමියේ පිළිස්සීමත් අවසාන පියවර ලෙස පොහොර සැකසීමත් යොදා ගැනීම",
        "පළමු ප්‍රමුඛතාව ලෙස ගංගාවලට මුදා හැරීමත් අවසාන පියවර ලෙස ප්‍රතිචක්‍රීකරණයත් යොදා ගැනීම",
        "පළමු ප්‍රමුඛතාව ලෙස භූමියේ වැළලීමත් අවසාන පියවර ලෙස නැවත භාවිතය අත්හැරීමත් යොදා ගැනීම",
        "මීතොටමුල්ල කසළ කන්ද කඩා වැටීම විවෘත කසළ බැහැර කිරීමේ (Open Dumping) බරපතල අනතුර පෙන්වා දුන් ශ්‍රී ලාංකික ඛේදවාචකයකි."),
      q(t, "'නගර කසළ කඳු පිපිරීමට හා ගිනි ගැනීමට' ප්‍රධාන රසායනික හේතුව කුමක්ද?",
        "විවෘත කසළ ගොඩවල් ඇතුළත කාබනික අපද්‍රව්‍ය ඔක්සිජන් රහිතව දිරාපත් වීමෙන් මීතේන් වායුව රැස්වීම",
        "කසළ කඳු පතුලේ උෂ්ණත්වය ශූන්‍යයට වඩා පහළ බැස ජලය අයිස් බවට පත්වීම",
        "වායුගෝලීය නයිට්‍රජන් වායුව කසළ තුළ දියවී ක්ෂාරීය සිසිල් ද්‍රාවණයක් නිර්මාණය වීම",
        "අපද්‍රව්‍ය අතර ඇති පස් ස්තර මගින් ඔක්සිජන් වායුව සම්පූර්ණයෙන්ම ද්‍රව බවට හැරවීම",
        "එබැවින් කාබනික අපද්‍රව්‍ය වෙන් කර කොම්පෝස්ට් හෝ ජීව වායුව (Biogas) නිපදවීම කසළ කඳු අවදානම නැති කරන ප්‍රධාන විසඳුමකි."),
      q(t, "'හරිතාගාර වායු විමෝචනය' අනුව 'ශුද්ධ ශූන්‍ය විමෝචනය' (Net-Zero Emissions) යන්නෙන් අදහස් කරන්නේ කුමක්ද?",
        "හරිතාගාර වායු විමෝචනය අවම කර ඉතිරි ප්‍රමාණය වනාන්තර හා කාබන් අවශෝෂක මගින් සමතුලිත කිරීම",
        "පෘථිවියේ සියලුම කර්මාන්තශාලා සහ ප්‍රවාහන පද්ධති සම්පූර්ණයෙන්ම වසා දමා නිෂ්පාදනය නතර කිරීම",
        "වායුගෝලයට මුදා හරින කාබන් ඩයොක්සයිඩ් ප්‍රමාණය වාර්ෂිකව දෙගුණයකින් ඉහළ නැංවීමට පියවර ගැනීම",
        "සූර්ය බලය හා සුළං බලය භාවිතය තහනම් කර ෆොසිල ඉන්ධන දහනය පමණක් ප්‍රවර්ධනය කිරීම",
        "දේශගුණික අර්බුදය පාලනය කිරීමට 2050 වන විට ගෝලීය Net-Zero ඉලක්කය සපුරා ගැනීමට රටවල් රැසක් ප්‍රතිඥා දී ඇත."),
      q(t, "'දේශගුණික විපර්යාස අවම කිරීම (Mitigation)' සහ 'දේශගුණික විපර්යාසවලට අනුවර්තනය වීම (Adaptation)' අතර වෙනස කුමක්ද?",
        "Mitigation හරිතාගාර වායු අඩු කරන අතර Adaptation මගින් පවතින බලපෑම්වලට ඔරොත්තු දෙන ලෙස හැඩගැසේ",
        "මෙම ක්‍රියාවලි දෙකම ෆොසිල ඉන්ධන භාවිතය ඉහළ නැංවීම සඳහා යොදා ගන්නා එකම සැලැස්මකි",
        "Adaptation යනු කාබන් විමෝචනය වැඩි කිරීම වන අතර Mitigation යනු වනාන්තර කපා හෙළීමයි",
        "Mitigation මගින් කාලගුණය වෙනස් කරන අතර Adaptation මගින් ගොවිතැන් කටයුතු සම්පූර්ණයෙන් නවතයි",
        "ශ්‍රී ලංකාව ගෝලීය විමෝචනයෙන් 0.1% කටත් වඩා අඩු කොටසක් නිකුත් කළද දේශගුණික බලපෑම්වලට දැඩිව ගොදුරු වන බැවින් අනුවර්තනය (Adaptation) ඉතා වැදගත්ය."),
      q(t, "'තෘණ බිම් හා වෙරළබඩ කඩොලාන' 'නීල කාබන්' (Blue Carbon) පරිසර පද්ධති ලෙස හැඳින්වෙන්නේ ඇයි?",
        "කඩොලාන හා මුහුදු තෘණ ගොඩබිම් වනාන්තරවලට වඩා වැඩි කාබන් ප්‍රමාණයක් මඩ පසෙහි තැන්පත් කරන බැවිනි",
        "එම වෙරළබඩ ශාකවල පත්‍ර හා මුල් සියල්ල නිල් පැහැයෙන් දිස්වන විශේෂ වර්ණකයක් දරන බැවිනි",
        "මෙම පරිසර පද්ධති මගින් වායුගෝලයට විශාල කාබන් ඩයොක්සයිඩ් ප්‍රමාණයක් නිරන්තරයෙන් මුදා හරින බැවිනි",
        "ඒවා සාගරයේ කිලෝමීටර ගණනක් ගැඹුරු අගාධ පතුලේ හිරු එළිය නොමැතිව වැඩෙන බැවිනි",
        "ශ්‍රී ලංකාව කඩොලාන පරිසර පද්ධති ආරක්ෂා කිරීමේ ජාත්‍යන්තර ගිවිසුම්වලට හා සංරක්ෂණ වැඩසටහන්වලට ප්‍රමුඛත්වය දී ඇත."),
      q(t, "'වෙරළ ඛාදනය' (Coastal Erosion) ස්වාභාවික මුහුදු රළට අමතරව මානව ක්‍රියාකාරකම් නිසා උග්‍ර වන්නේ කෙසේද?",
        "කොරල් පර කැඩීම, ගංගා හා මුහුදු වැලි අධිකව ගොඩදැමීම සහ කඩොලාන විනාශ කර ඉදිකිරීම් කිරීම",
        "වෙරළ තීරය දිගේ කඩොලාන පැළ සිටුවීම සහ ස්වාභාවික වැලි කඳු පද්ධති සංරක්ෂණය කිරීම",
        "ගංගා මෝය ආශ්‍රිත රොන්මඩ සහ අපද්‍රව්‍ය ක්‍රමවත්ව පිරිසිදු කර ජල බැස්ම විධිමත් කිරීම",
        "නොගැඹුරු මුහුදේ කොරල් පර නීති මගින් ආරක්ෂා කර සමුද්‍ර ජීවී අභිජනන කලාප පිහිටුවීම",
        "වෙරළ සංරක්ෂණ හා වෙරළ සම්පත් කළමනාකරණ දෙපාර්තමේන්තුව (CCD) ගල් වැටි (Revetments), තරංග කඩන (Breakwaters) හා කෘත්‍රිම වැලි පෝෂණය (Beach Nourishment) භාවිත කරයි."),
      q(t, "'නිවර්තන සුළි කුණාටුවකදී' (Cyclone) විශාලතම ජීවිත හා දේපළ විනාශය බොහෝ විට සිදුවන්නේ සුළඟින් පමණක් නොව කුමන සාගර සංසිද්ධිය නිසාද?",
        "අඩු පීඩනය හා තද සුළං නිසා මුහුදු ජලය ගොඩබිමට තල්ලු වන කුණාටු උදම් රළ (Storm Surge)",
        "සාගර පතුලේ භූ තැටි ගැටීම නිසා ඇතිවන ගැඹුරු කිඳා බැසීම් හා ගිනිකඳු විදාරණ",
        "ධ්‍රැව ප්‍රදේශවල ග්ලැසියර ක්ෂණිකව දිය වී ගොඩබිම් මතුපිට හිම තට්ටු තැන්පත් වීම",
        "චන්ද්‍ර ගුරුත්වාකර්ෂණය හීන වීම නිසා වඩදිය මට්ටම අසාමාන්‍ය ලෙස පහළ බැස වෙරළ වියළීම",
        "1978 මඩකලපුව සුළි කුණාටුව ශ්‍රී ලංකාවට දැඩි හානි සිදු කළ ඓතිහාසික නිවර්තන සුළි කුණාටුවකි."),
      q(t, "'පාරිසරික බලපෑම් තක්සේරුව' (EIA - Environmental Impact Assessment) නීතිමය වශයෙන් ක්‍රියාත්මක කරනු ලබන ශ්‍රී ලංකාවේ ප්‍රධාන ආයතනය කුමක්ද?",
        "මධ්‍යම පරිසර අධිකාරිය (CEA)",
        "ශ්‍රී ලංකා මහ බැංකුව",
        "තැපැල් දෙපාර්තමේන්තුව",
        "ජාතික විභාග දෙපාර්තමේන්තුව",
        "ජාතික පාරිසරික පනත යටතේ නියමිත මහා පරිමාණ ව්‍යාපෘති සඳහා අනුමැතිය ලබා ගැනීමට මහජන අදහස් විමසීමද EIA ක්‍රියාවලියට අයත් වේ."),
      q(t, "'ගංවතුර ආපදා අවම කිරීමේදී ව්‍යුහාත්මක (Structural)' හා 'ව්‍යුහාත්මක නොවන (Non-structural)' පියවර අතර නිවැරදි උදාහරණ යුගලය කුමක්ද?",
        "ව්‍යුහාත්මක ක්‍රමය ගං ඉවුරු බැමි ඉදිකිරීම වන අතර ව්‍යුහාත්මක නොවන ක්‍රමය කලාපකරණය හා පූර්ව අනතුරු ඇඟවීමයි",
        "ව්‍යුහාත්මක ක්‍රමය කොන්ක්‍රීට් බැමි තැනීම වන අතර ව්‍යුහාත්මක නොවන ක්‍රමය ගංගා හරහා වේලි බැඳීමයි",
        "ව්‍යුහාත්මක ක්‍රමය වනාන්තර වැවීම වන අතර ව්‍යුහාත්මක නොවන ක්‍රමය කිසිදු පියවරක් නොගෙන අත්හැරීමයි",
        "ව්‍යුහාත්මක ක්‍රමය රක්ෂණ ක්‍රම ඇති කිරීම වන අතර ව්‍යුහාත්මක නොවන ක්‍රමය ජලාශ පතුල් ගැඹුරු කිරීමයි",
        "ලාභදායී හා තිරසාර ආපදා කළමනාකරණයේදී මෙම ක්‍රම දෙකම සංයෝජනය කෙරේ."),
      q(t, "'ශ්‍රී ලංකාවේ ගංවතුර පූර්ව අනතුරු ඇඟවීම් හා ජලාශ වාන් දොරටු කළමනාකරණය' සිදු කරන ප්‍රධාන ආයතනය කුමක්ද?",
        "වාරිමාර්ග දෙපාර්තමේන්තුව සහ මහවැලි අධිකාරිය",
        "ශ්‍රී ලංකා රේගු දෙපාර්තමේන්තුව",
        "ආගමන හා විගමන දෙපාර්තමේන්තුව",
        "මෝටර් රථ ප්‍රවාහන දෙපාර්තමේන්තුව",
        "කැලණි, කළු, ගිං, නිල්වලා හා අත්තනගලු ඔය ජල මාපක දත්ත අනුව ගංවතුර මට්ටම් නිරන්තරයෙන් නිරීක්ෂණය කෙරේ."),
      q(t, "'ප්‍රජා මූලික ආපදා කළමනාකරණය' (Community-Based Disaster Risk Management - CBDRM) සාර්ථක ආපදා ප්‍රතිචාරයකට අත්‍යවශ්‍ය වන්නේ ඇයි?",
        "බාහිර සහන කණ්ඩායම් පැමිණීමට පෙර පළමු ප්‍රතිචාර දක්වන්නන් වන්නේ එම ප්‍රදේශයේ පුහුණු ජනතාව බැවිනි",
        "ග්‍රාමීය ප්‍රජාව ආපදා අවදානම් පිළිබඳ කිසිදු දැනුමක් හෝ අත්දැකීමක් නොමැති පිරිසක් වන බැවිනි",
        "ඕනෑම හදිසි ආපදාවකදී විදේශීය හා ජාතික සහන කණ්ඩායම් තත්පර කිහිපයකින් එම ස්ථානයට ළඟා වන බැවිනි",
        "ආපදා නීතිය අනුව ගම්වාසීන්ට ප්‍රථමාධාර හෝ මුදවා ගැනීමේ කටයුතුවලට සහභාගී වීම තහනම් කර ඇති බැවිනි",
        "ග්‍රාම නිලධාරී වසම් මට්ටමින් ආපදා කළමනාකරණ කමිටු, ආරක්ෂිත ගමන් මාර්ග සිතියම් හා ප්‍රථමාධාර පුහුණුව ලබා දීම මෙහි අරමුණයි."),
      q(t, "'ස්වාභාවික විපතකදී ජලය මගින් බෝවන රෝග' (Water-borne Diseases - උදා: පාචනය, කොලරාව, හෙපටයිටිස් A, මී උණ/Leptospirosis) ගංවතුරට පසු පැතිරෙන්නේ ඇයි?",
        "වැසිකිළි වළවල් හා කසළ ගංවතුරට මිශ්‍ර වීමෙන් පානීය ළිං අපවිත්‍ර වීමත් මඩ ජලයේ ගැවසීමත් නිසා",
        "ගංවතුර කාලයේදී පොළොව යට ඇති භූගත ජල උල්පත් සම්පූර්ණයෙන්ම පිරිසිදු වී බැක්ටීරියා විනාශ වන නිසා",
        "ගංවතුර හේතුවෙන් මදුරුවන් හා කෘමි සතුන් ප්‍රදේශයෙන් සම්පූර්ණයෙන්ම අතුරුදහන් වී පරිසරය වියළෙන නිසා",
        "අධික වර්ෂාව සමඟ පතිත වන වැසි ජලය නටන උණුසුම් මට්ටමේ පවතින බැවින් ජලජ ක්ෂුද්‍රජීවීන් වඳ වන නිසා",
        "ගංවතුර බැස ගිය පසු ළිං පිරිසිදු කර ක්ලෝරීන් යෙදීමත්, ජලය උතුරුවා පානය කිරීමත් අත්‍යවශ්‍ය සෞඛ්‍ය පියවරකි."),
      q(t, "'නොදිරන කෘෂි රසායනික හා භූගත පානීය ජල දූෂණය' වැළැක්වීම සඳහා අපද්‍රව්‍ය හා පළිබෝධනාශක කළමනාකරණයේදී ගත යුතු ප්‍රධාන පියවර කුමක්ද?",
        "ඒකාබද්ධ පළිබෝධ කළමනාකරණය (IPM), නියමිත මාත්‍රාව භාවිතය හා හිස් බෝතල් ජල මූලාශ්‍රවල නොසේදීම",
        "භාවිත කළ හිස් රසායනික බෝතල් හා ඉතිරි ද්‍රාවණ ගලා යන ගංගාවලට හා ඇළ මාර්ගවලට මුදා හැරීම",
        "කෘමි හානි නැවැත්වීම සඳහා නිර්දේශිත මාත්‍රාව මෙන් දස ගුණයක රසායනික ප්‍රමාණයක් වගාවට ඉසීම",
        "වගා ළිං තුළට කෙලින්ම කෘෂි රසායන දිය කර පොම්ප මගින් කුඹුරු හා ගෙවතු බිම්වලට යෙදීම",
        "ජල මූලාශ්‍ර හා රක්ෂිත ඉවුරු (Riparian Buffers) ගස් වැවීමෙන් රසායනික ගලා යාම පෙරා හරියි."),
      q(t, "'රැම්සා තෙත් බිම් සම්මුතිය' (Ramsar Convention on Wetlands - 1971) යටතේ ශ්‍රී ලංකාවේ බූන්දල, ආනවිලුන්දාව, මාදු ගඟ, කුමන, විල්පත්තු හා වන්කාලෙයි ආරක්ෂා කරන්නේ ඇයි?",
        "ජලජ පක්ෂීන්ගේ වාසභූමි, ගංවතුර අවශෝෂණය හා ජල පිරිසිදු කිරීම සපයන තෙත් බිම් ලෙස සංරක්ෂණය කිරීමට",
        "මහා පරිමාණ කර්මාන්තශාලා හා වාණිජ ගබඩා සංකීර්ණ ඉදිකිරීම සඳහා පස් පුරවා ගොඩ කිරීමට",
        "වගුරු බිම් සම්පූර්ණයෙන්ම සිඳුවා දමා කෘත්‍රිම ගුවන් තොටුපළ හා අධිවේගී මාර්ග පද්ධති තැනීමට",
        "නාගරික ඝන අපද්‍රව්‍ය හා ප්ලාස්ටික් කසළ බැහැර කරන විවෘත කසළ අංගන ලෙස භාවිත කිරීමට",
        "ශ්‍රී ලංකාවේ අගනුවර කොළඹ ලෝකයේ පළමු 'රැම්සා තෙත් බිම් නගරවලින්' (Ramsar Wetland City) එකක් ලෙසද පිළිගැනීමට ලක්ව ඇත."),
      q(t, "'හරිත පටි හා තිරසාර නගර සැලසුම්කරණය' (Sustainable Cities - SDG 11) යටතේ ගංවතුර හා තාප තරංග අවම කිරීමට ගත හැකි නාගරික පියවර මොනවාද?",
        "විනිවිද යන පදික වේදිකා, වැව් හා ඇළ මාර්ග පුළුල් කිරීම සහ නාගරික හරිත උද්‍යාන වැඩි කිරීම",
        "නගරයේ පවතින සියලුම වැව් හා වගුරු බිම් පස් දමා ගොඩ කර වාණිජ ගොඩනැගිලි තැනීම",
        "වැසි ජලය පසට උරා ගැනීම නැවැත්වීමට මුළු නගර පෘෂ්ඨයම ඝන කොන්ක්‍රීට් තට්ටුවකින් ආවරණය කිරීම",
        "මාර්ග දෙපස ඇති සියලුම සෙවණ ගෙනෙන ගස් කපා දමා වීදි පළල් රථගාල් බවට පත් කිරීම",
        "ස්වාභාවික ජල බැස්මට ඉඩ සැලසීම කොන්ක්‍රීට් බැමිවලට වඩා ලාභදායී හා ආරක්ෂිත වේ."),
      q(t, "'භූගර්භ විද්‍යාත්මක ආපදා අතර ද්‍රවීකරණය' (Soil Liquefaction) යනු භූමිකම්පාවකදී කුමන ස්ථානවල සිදුවන භයානක සංසිද්ධියක්ද?",
        "ජලයෙන් සංතෘප්ත ලිහිල් වැලි සහිත පස භූමිකම්පා කම්පනයෙන් දියර මඩක් මෙන් හැසිරී ගොඩනැගිලි ගිලා බැසීම",
        "කඳුකර ප්‍රදේශවල පවතින ඝන ග්‍රැනයිට් හා ක්වාර්ට්ස් පර්වත අධික තාපයෙන් දියවී ගලා යාම",
        "වායුගෝලයේ ඇති වැසි වළාකුළු භූමිකම්පා තරංග නිසා ක්ෂණිකව ඝන අයිස් තට්ටු බවට පත් වීම",
        "වියළි කාන්තාරවල ඇති ලිහිල් වැලි කඳු භූමිකම්පාවකින් පසු සදාකාලික තද පර්වත බවට හැරීම",
        "1964 නිගාටා (ජපානය) හා 2011 ක්‍රයිස්ට්චර්ච් (නවසීලන්තය) භූමිකම්පාවලදී මෙය දැඩි හානි ඇති කළේය."),
      q(t, "'ගිනිකඳු විදාරණයකදී' (Volcanic Eruption) ලාවා ගලා යාමටත් වඩා වේගවත් හා මාරාන්තික වන උපද්‍රව දෙක කුමක්ද?",
        "අධික උණුසුම් වායු හා අළු සහිත පයිරොක්ලාස්ටික් ප්‍රවාහ (Pyroclastic Flows) සහ ලාහාර් මඩ ගංවතුර",
        "කිලෝමීටර ගණනාවක් දුරට ඇසෙන සුළු ශබ්ද තරංග සහ අහසේ ඇතිවන වලාකුළු රටා පමණක් වීම",
        "ගිනිකන්ද අවට ප්‍රදේශයට කෙටි වේලාවක් පතිත වන සිසිල් මඳ වැස්ස සහ සෞම්‍ය සුළං ප්‍රවාහ",
        "ගිනිකඳු මුදුන අවට උෂ්ණත්වය අඩු වීම නිසා බෑවුම් දිගේ ඇතිවන සුදු පැහැති මෘදු හිම පතනය",
        "ලොව හිම මුදුන් සහිත ගිනිකඳු පිපිරෙන විට අයිස් දිය වී ගිනිකඳු අළු සමඟ මිශ්‍ර වී කොන්ක්‍රීට් මෙන් ගලා යන 'ලාහාර්' ඉතා භයානකය."),
      q(t, "'කාලගුණික ආන්තික සිදුවීම්' (Extreme Weather Events) අතර 'තාප තරංග' (Heatwaves) කෘෂිකර්මයට හා මිනිස් සෞඛ්‍යයට බලපාන්නේ කෙසේද?",
        "දින ගණනාවක් අධික උණුසුම පැවතීමෙන් විජලනය, තාප ආඝාතය, විදුලි අධිබර වීම් හා බෝග මැලවී යාම සිදුවේ",
        "වායුගෝලීය උෂ්ණත්වය අධික ලෙස පහළ වැටීමෙන් අයිස් කැට වර්ෂාවක් පතිත වී භූමිය සිසිල් වේ",
        "වාෂ්පීකරණය නතර වීම හේතුවෙන් වැව් හා ජලාශවල පානීය ජල සැපයුම ස්වාභාවිකව දෙගුණයකින් ඉහළ යයි",
        "පසේ තෙතමනය අධික වී වී හා එළවළු බෝග වේගයෙන් වර්ධනය වී අස්වැන්න අසාමාන්‍ය ලෙස වැඩි වේ",
        "දේශගුණික විපර්යාස හේතුවෙන් ලොව පුරා තාප තරංගවල සංඛ්‍යාතය හා තීව්‍රතාව සීඝ්‍රයෙන් ඉහළ යමින් පවතී."),
      q(t, "'නියඟ හා ගංවතුර ආපදා කළමනාකරණයේදී ශ්‍රී ලංකාවේ කාලගුණ විද්‍යා දෙපාර්තමේන්තුව' ඉටු කරන ප්‍රධාන කාර්යභාරය කුමක්ද?",
        "රේඩාර්, චන්ද්‍රිකා හා මධ්‍යස්ථාන දත්ත මගින් තද වැසි, අකුණු, සුළං හා සුළි කුණාටු පූර්ව අනතුරු ඇඟවීම් නිකුත් කිරීම",
        "විශාල ගංගා හරහා කොන්ක්‍රීට් වේලි, වාරි ඇළ මාර්ග හා රැඳවුම් ජලාශ පද්ධති ඉදිකර නඩත්තු කිරීම",
        "ආපදාවලින් තුවාල ලැබූ රෝගීන්ට ප්‍රතිකාර කිරීම සඳහා දිවයින පුරා ජාතික රෝහල් ජාලය පාලනය කිරීම",
        "නාගරික ප්‍රදේශවල ඉදිකරන වාණිජ ගොඩනැගිලි හා නිවාස සැලසුම් නීතිමය වශයෙන් අනුමත කර ලියාපදිංචි කිරීම",
        "ධීවරයන් හා නාවිකයන් මුහුදු යාමට පෙර කාලගුණ අනාවැකි හා රතු නිවේදන අනුගමනය කිරීම ජීවිතාරක්ෂාවට අත්‍යවශ්‍ය වේ."),
      q(t, "'අකුණු අනතුරු' (Lightning Hazards) ශ්‍රී ලංකාවේ වැඩිපුරම වාර්තා වන්නේ කුමන කාලගුණික කාලසීමාව තුළද?",
        "පළමු හා දෙවන අන්තර්-මෝසම් කාලවල සවස් කාලයේ ඇතිවන සංවහන ගිගුරුම් සහිත වැසි සමඟ",
        "ජනවාරි මාසයේ උදෑසන කාලයේ ඊසානදිගින් හමන වියළි හා සිසිල් මෝසම් සුළං ප්‍රවාහ සමඟ",
        "ජුනි මාසයේ වියළි කලාපයේ පවතින ඉහළ වායු පීඩනය සහිත පැහැදිලි වලාකුළු රහිත අහස සමඟ",
        "මධ්‍යම රාත්‍රී කාලයේ කඳුකරයේ සිට මුහුද දෙසට හමා යන මෘදු ගොඩ සුළං ප්‍රවාහයන් සමඟ",
        "අකුණු ගසන විට විවෘත පිට්ටනි, උස් ගස් යට, ජලාශ තුළ හා රැහැන් සහිත විදුලි උපකරණ අසල රැඳීමෙන් වැළකී ගොඩනැගිල්ලක් හෝ සංවෘත වාහනයක් තුළට යා යුතුය."),
      q(t, "'සාගර ආම්ලීකරණය' (Ocean Acidification) යනු කුමක්ද සහ එය සමුද්‍ර පරිසර පද්ධතිවලට හානි කරන්නේ කෙසේද?",
        "අතිරික්ත කාබන් ඩයොක්සයිඩ් සාගර ජලයේ දියවී pH අගය පහළ වැටී කොරල් හා කවච දිය වී යාම",
        "ගංගා මගින් රැගෙන එන ස්වාභාවික ඛනිජ ලවණ නිසා සාගර ජලය පැණි රස හා ඝන ස්වභාවයට පත් වීම",
        "හිරු එළිය වැඩි වීම නිසා මුහුදු ජලයේ pH අගය දහහතර දක්වා ඉහළ ගොස් ක්ෂාරීය බව වැඩි වීම",
        "මුහුදු ජලයේ ඝනත්වය අඩු වීම නිසා ගැඹුරු සාගරයේ මත්ස්‍යයන්ට පිහිනීම සහ හුස්ම ගැනීම පහසු වීම",
        "මෙය දේශගුණික විපර්යාසයේ 'දෙවන CO2 ගැටලුව' ලෙස හැඳින්වෙන අතර ධීවර කර්මාන්තයටද තර්ජනයකි."),
      q(t, "'තෙල් කාන්දු' (Marine Oil Spills) සාගර පරිසරයට ඇති කරන ක්ෂණික හා දිගුකාලීන හානි මොනවාද?",
        "ජලය මතුපිට තෙල් පටලයකින් හිරු එළිය හා ඔක්සිජන් අවහිර වී මුහුදු පක්ෂීන්, කඩොලාන හා මසුන් විනාශ වීම",
        "තෙල් ස්තරය මගින් මුහුදු ජලයේ ඇති සියලුම විෂ ද්‍රව්‍ය පෙරා ජලය වඩාත් පිරිසිදු බවට පත් කිරීම",
        "කොරල් පරවලට අතිරේක පෝෂ්‍ය පදාර්ථ ලැබී ඒවා සාමාන්‍ය වේගයට වඩා දෙගුණයකින් වේගවත්ව වර්ධනය වීම",
        "මුහුදු පක්ෂීන්ගේ පිහාටු ජලයෙන් ආරක්ෂා වී සාගරය මත වේගයෙන් පිහිනීමට හා කිමිදීමට පහසු වීම",
        "ශ්‍රී ලංකාව ප්‍රධාන නැගෙනහිර-බටහිර තෙල් නැව් මාර්ගයට ආසන්නයේ පිහිටි බැවින් MT New Diamond හා X-Press Pearl වැනි නෞකා අනතුරුවලින් අපගේ සාගර ආරක්ෂණ සූදානම වැදගත් බව පෙන්නුම් කළේය."),
      q(t, "'ගංවතුර හා ක්ෂණික නායයෑම්වලට හසු වූ ප්‍රදේශවල' විදුලි පද්ධති හා ජල නල සම්බන්ධයෙන් අනුගමනය කළ යුතු ප්‍රධාන ආරක්ෂිත පියවර කුමක්ද?",
        "ජලය ඇතුළු වීමට පෙර ප්‍රධාන විදුලි ස්විචය විසන්ධි කර කඩා වැටුණු රැහැන්වලින් ඈත්ව සිටීම",
        "නිවස තුළට ජලය ගලා එන විට තෙත් අතින් විදුලි ස්විච් හා ප්ලග් පුවරු පරීක්ෂා කර බැලීම",
